/* v1.5.4 — structural duplication and authoring comments. */
const DuplicateController={
  uniqueId(base){let stem=(String(base||'elemento')+'-copy').replace(/[^A-Za-z0-9_:\-.]/g,'-'),id=stem,n=2;while(document.getElementById(id)){id=stem+'-'+n++}return id},
  scrubEditorState(root){for(const e of [root,...root.querySelectorAll('*')]){TRANSIENT_ATTRS.forEach(a=>e.removeAttribute(a));e.removeAttribute('data-ie-history-id');e.removeAttribute('data-ie-comment-anchor');e.removeAttribute('data-ie-comments');}},
  remapIds(root){const map=new Map(),nodes=[root,...root.querySelectorAll('[id]')].filter(e=>e.id);for(const e of nodes){const old=e.id,nu=this.uniqueId(old);map.set(old,nu);e.id=nu}
    const tokenAttrs=['for','aria-labelledby','aria-describedby','aria-controls','aria-owns','headers','list','form'];
    for(const e of [root,...root.querySelectorAll('*')]){for(const a of tokenAttrs){if(!e.hasAttribute(a))continue;const vals=e.getAttribute(a).split(/\s+/).map(v=>map.get(v)||v);e.setAttribute(a,vals.join(' '))}
      for(const a of ['href','xlink:href']){const v=e.getAttribute(a);if(v?.startsWith('#')&&map.has(v.slice(1)))e.setAttribute(a,'#'+map.get(v.slice(1)))}
      for(const a of ['clip-path','filter','mask','fill','stroke','style']){const v=e.getAttribute(a);if(!v)continue;let out=v;for(const [old,nu] of map)out=out.replaceAll('url(#'+old+')','url(#'+nu+')');if(out!==v)e.setAttribute(a,out)}
    }return map},
  nudgeAbsolute(clone,source){const cs=getComputedStyle(source);if(!['absolute','fixed'].includes(cs.position))return;const r=source.getBoundingClientRect(),p=source.offsetParent?.getBoundingClientRect?.()||{left:0,top:0};clone.style.right='';clone.style.bottom='';clone.style.left=px(r.left-p.left+16);clone.style.top=px(r.top-p.top+16)},
  duplicate(){const els=selection();if(els.length!==1){notify('Para duplicar, selecione apenas um elemento.');return null}const source=els[0],parent=source.parentNode;if(!parent||Utils.isProtected(source)){notify('Este elemento não pode ser duplicado.');return null}
    TextEditor.finishColor();H.commitContinuous();const clone=source.cloneNode(true);this.scrubEditorState(clone);this.remapIds(clone);this.nudgeAbsolute(clone,source);const next=source.nextSibling;
    parent.insertBefore(clone,next);const undo=()=>{clone.remove();SE.select(source);AuthoredManager.refresh();CommentManager.refreshRegistry();syncUI()},redo=()=>{const anchor=source.isConnected?source.nextSibling:(next?.isConnected?next:null);if(source.isConnected)source.parentNode.insertBefore(clone,anchor);else if(parent.isConnected)parent.insertBefore(clone,next?.isConnected?next:null);SE.select(clone);AuthoredManager.refresh();CommentManager.refreshRegistry();syncUI()};
    H.pushCustom('Duplicar elemento',undo,redo);SE.select(clone);BaselineManager.ensure(clone);AuthoredManager.refresh();syncUI();notify('Elemento duplicado.');return clone}
};

const CommentManager={
  ATTR:'data-ie-comments',ANCHOR:'data-ie-comment-anchor',editingId:null,editingTarget:null,
  protocol:'Records with type="llm_task" and status="open" are explicit user-requested edits. Apply each task to the element whose data-ie-comment-anchor matches record.target. Records with type="note" are context only and MUST NOT be treated as modification requests. Resolved tasks MUST NOT be applied.',
  parse(el){try{const a=JSON.parse(el?.getAttribute(this.ATTR)||'[]');return Array.isArray(a)?a:[]}catch(_){return[]}},
  writeRaw(el,anchor,records){if(anchor)el.setAttribute(this.ANCHOR,anchor);else el.removeAttribute(this.ANCHOR);if(records?.length)el.setAttribute(this.ATTR,JSON.stringify(records));else el.removeAttribute(this.ATTR)},
  meta(el){return{anchor:el?.getAttribute(this.ANCHOR)||'',records:this.parse(el)}},
  applyMeta(el,meta){if(!el?.isConnected)return;this.writeRaw(el,meta.anchor,meta.records);this.refreshRegistry();syncUI()},
  ensureAnchor(el){let a=el.getAttribute(this.ANCHOR);if(a)return a;do{a='ieca-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,8)}while(document.querySelector(`[${this.ANCHOR}="${CSS.escape(a)}"]`));return a},
  id(){return'iec-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,8)},
  rangeMeta(el){if(selection().length!==1||!['text','link','table_cell'].includes(SE.contextOf(el)))return null;const r=TR.resolve();if(!r||r.mode!=='range')return null;const quote=r.range.toString().trim();return quote?{quote:quote.slice(0,1000),start:r.start,end:r.end}:null},
  all(root=document){return [...root.querySelectorAll(`[${this.ATTR}]`)].flatMap(el=>{const anchor=el.getAttribute(this.ANCHOR)||'';return this.parse(el).map(r=>({...r,target:anchor||r.target||'',targetLabel:r.targetLabel||U.label(el)}))})},
  add(){const el=selected(),text=$('#ie-comment-text').value.trim(),type=$('#ie-comment-type').value;if(selection().length!==1||!el){notify('Selecione um único elemento para comentar.');return}if(!text){notify('Escreva o comentário antes de adicionar.');return}
    const before=this.meta(el),anchor=before.anchor||this.ensureAnchor(el),records=[...before.records],now=new Date().toISOString(),range=this.rangeMeta(el);const rec={id:this.id(),type:type==='llm_task'?'llm_task':'note',status:type==='llm_task'?'open':'info',text,createdAt:now,updatedAt:now,target:anchor,targetLabel:U.label(el),...(range?{range}: {})};records.push(rec);const after={anchor,records};this.writeRaw(el,anchor,records);H.pushCustom(type==='llm_task'?'Adicionar ajuste para LLM':'Adicionar nota',()=>this.applyMeta(el,before),()=>this.applyMeta(el,after));this.editingId=null;$('#ie-comment-text').value='';$('#ie-comment-cancel-edit').hidden=true;this.refreshRegistry();syncUI();notify(type==='llm_task'?'Ajuste para LLM adicionado.':'Nota adicionada.')},
  edit(id){const el=selected(),rec=this.parse(el).find(x=>x.id===id);if(!rec)return;this.editingId=id;this.editingTarget=el;$('#ie-comment-type').value=rec.type;$('#ie-comment-text').value=rec.text;$('#ie-comment-add').textContent='Salvar comentário';$('#ie-comment-cancel-edit').hidden=false;$('#ie-comment-text').focus()},
  saveEdit(){const el=selected();if(!el||!this.editingId||this.editingTarget!==el){this.cancelEdit();notify('A seleção mudou; abra o comentário novamente para editar.');return}const text=$('#ie-comment-text').value.trim();if(!text){notify('O comentário não pode ficar vazio.');return}const before=this.meta(el),records=before.records.map(r=>r.id===this.editingId?{...r,type:$('#ie-comment-type').value==='llm_task'?'llm_task':'note',status:$('#ie-comment-type').value==='llm_task'?(r.status==='resolved'?'resolved':'open'):'info',text,updatedAt:new Date().toISOString()}:r),after={anchor:before.anchor,records};this.writeRaw(el,after.anchor,records);H.pushCustom('Editar comentário',()=>this.applyMeta(el,before),()=>this.applyMeta(el,after));this.cancelEdit();this.refreshRegistry();syncUI();notify('Comentário atualizado.')},
  cancelEdit(){this.editingId=null;this.editingTarget=null;$('#ie-comment-text').value='';$('#ie-comment-add').textContent='Adicionar';$('#ie-comment-cancel-edit').hidden=true},
  remove(id){const el=selected();if(!el)return;const before=this.meta(el),records=before.records.filter(r=>r.id!==id),after={anchor:records.length?before.anchor:'',records};this.writeRaw(el,after.anchor,records);H.pushCustom('Excluir comentário',()=>this.applyMeta(el,before),()=>this.applyMeta(el,after));if(this.editingId===id)this.cancelEdit();this.refreshRegistry();syncUI();notify('Comentário removido.')},
  toggleResolved(id){const el=selected();if(!el)return;const before=this.meta(el),records=before.records.map(r=>r.id===id&&r.type==='llm_task'?{...r,status:r.status==='resolved'?'open':'resolved',updatedAt:new Date().toISOString()}:r),after={anchor:before.anchor,records};this.writeRaw(el,after.anchor,records);H.pushCustom('Alterar status do ajuste',()=>this.applyMeta(el,before),()=>this.applyMeta(el,after));this.refreshRegistry();syncUI()},
  createRegistry(root=document){const records=this.all(root);return{schema:'inline-editor-comments/v1',generatedAt:new Date().toISOString(),instructionsForLLM:this.protocol,records}},
  refreshRegistry(){/* registry is materialized on serialization; live DOM stays light */},
  prepareClone(clone,{clean=false}={}){const old=clone.querySelector('#ie-comments-data');old?.remove();const walker=document.createTreeWalker(clone,NodeFilter.SHOW_COMMENT),rm=[];while(walker.nextNode())if(walker.currentNode.data.includes('INLINE-EDITOR-COMMENT-PROTOCOL'))rm.push(walker.currentNode);rm.forEach(n=>n.remove());
    if(clean){for(const e of clone.querySelectorAll(`[${this.ATTR}],[${this.ANCHOR}]`)){e.removeAttribute(this.ATTR);e.removeAttribute(this.ANCHOR)}return}
    const records=this.all(clone);if(!records.length)return;const head=clone.querySelector('head')||clone;const comment=document.createComment(' INLINE-EDITOR-COMMENT-PROTOCOL: '+this.protocol+' ');const script=document.createElement('script');script.id='ie-comments-data';script.type='application/json';script.setAttribute('data-ie-authored-comments','');script.textContent=JSON.stringify({schema:'inline-editor-comments/v1',instructionsForLLM:this.protocol,records},null,2);head.append(comment,script)},
  render(){const el=selected();if(this.editingId&&this.editingTarget!==el)this.cancelEdit();const list=$('#ie-comment-list'),summary=$('#ie-comment-summary'),hint=$('#ie-comment-range-hint'),badge=$('#ie-comment-badge');if(!list)return;const single=selection().length===1&&!!el,records=single?this.parse(el):[];$('#ie-comment-add').disabled=!single;$('#ie-comment-type').disabled=!single;$('#ie-comment-text').disabled=!single;
    list.replaceChildren();for(const r of records){const item=document.createElement('article');item.className='ie-comment-item';item.dataset.type=r.type;item.dataset.status=r.status||'';const meta=document.createElement('div');meta.className='ie-comment-meta';const kind=document.createElement('span');kind.className='ie-comment-kind';kind.textContent=r.type==='llm_task'?'Ajuste LLM':'Nota';meta.append(kind);if(r.type==='llm_task'){const st=document.createElement('span');st.className='ie-comment-kind';st.textContent=r.status==='resolved'?'Resolvido':'Aberto';meta.append(st)}const p=document.createElement('p');p.className='ie-comment-text';p.textContent=r.text;item.append(meta,p);if(r.range?.quote){const q=document.createElement('p');q.className='ie-comment-quote';q.textContent='Trecho: “'+r.range.quote+'”';item.append(q)}const actions=document.createElement('div');actions.className='ie-comment-actions';const edit=document.createElement('button');edit.type='button';edit.textContent='Editar';edit.onclick=()=>this.edit(r.id);actions.append(edit);if(r.type==='llm_task'){const res=document.createElement('button');res.type='button';res.textContent=r.status==='resolved'?'Reabrir':'Resolver';res.onclick=()=>this.toggleResolved(r.id);actions.append(res)}const del=document.createElement('button');del.type='button';del.textContent='Excluir';del.onclick=()=>this.remove(r.id);actions.append(del);item.append(actions);list.append(item)}
    const total=this.all(document).length,openTasks=this.all(document).filter(r=>r.type==='llm_task'&&r.status==='open').length;summary.textContent=single?`${records.length} neste elemento · ${total} no documento${openTasks?' · '+openTasks+' ajustes LLM abertos':''}`:`Selecione um único elemento. ${total} comentários no documento.`;const rr=single?this.rangeMeta(el):null;hint.textContent=rr?'O trecho selecionado será salvo como referência: “'+rr.quote.slice(0,140)+(rr.quote.length>140?'…':'')+'”':'O comentário será associado ao elemento inteiro.';
    if(badge){badge.hidden=!single||!records.length;badge.textContent=records.length===1?'1 comentário':records.length+' comentários';badge.dataset.openTask=String(records.some(r=>r.type==='llm_task'&&r.status==='open'))}
    const sub=$('#ie-subtab-comments');if(sub){const label='Comentários';sub.textContent=total?label+' '+total:label}
  },
  openTab(){SubTabController.setMain('more');SubTabController.setSub('more','comments')},
  install(){const add=$('#ie-comment-add');if(add)add.onclick=()=>this.editingId?this.saveEdit():this.add();$('#ie-comment-cancel-edit')?.addEventListener('click',()=>this.cancelEdit());$('#ie-comment-badge')?.addEventListener('click',()=>this.openTab());this.render()}
};
